import java.util.ArrayList;
import java.util.Comparator;
public class Main { public static void main(String[] args) { ArrayList<String> words = new ArrayList<>(); words.add("ant"); words.add("zebra"); words.add("bee"); words.sort(Comparator.reverseOrder()); System.out.println(words); } }

import java.util.ArrayList;
import java.util.Comparator;
public class Main { public static void main(String[] args) { ArrayList<String> words = new ArrayList<>(); words.add("pear"); words.add("fig"); words.add("plum"); words.sort(Comparator.comparingInt(String::length)); System.out.println(words); } }

import java.util.ArrayList;
import java.util.Comparator;
public class Main { public static void main(String[] args) { ArrayList<String> names = new ArrayList<>(); names.add("Ravi"); names.add("Asha"); names.add("Aman"); names.sort(Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder())); System.out.println(names); } }

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
public class Main {
    public static void main(String[] args) {
        List<Integer> values = new ArrayList<>(List.of(4, 2, 4, 8));
        System.out.println(Collections.frequency(values, 4));
        System.out.println(Collections.min(values));
        System.out.println(Collections.max(values));
        List<Integer> searchValues = new ArrayList<>(List.of(2, 4, 8));
        System.out.println(Collections.binarySearch(searchValues, 4));
        Collections.reverse(values);
        System.out.println(values);
    }
}
